import ifj26.*


def printLine(value: String): Unit =
  print(value)
  print("\n")

def square(n: Int) = n * n


def is_odd(n: Int): Boolean =
  if n / 2 * 2 != n then
    return true
  else
    return false


def remainder(n: Int, d: Int): Int = n - n / d * d


def gcd(a: Int, b: Int): Int =
  var x = a
  var y = b
  while y != 0 do
    val r = remainder(x, y)
    x = y
    y = r
  return x


def xor(p: Boolean, q: Boolean): Boolean =
  return (p || q) && !(p && q)


def is_prime(n: Int): Boolean =
  if n < 2 then
    return false
  var i = 2
  while i * i <= n do
    if remainder(n, i) == 0 then
      return false
    i = i + 1
  return true


def power(base: Int, exp: Int): Int =
  if exp == 0 then
    return 1
  val half = power(base, exp / 2)
  if is_odd(exp) then
    return half * half * base
  else
    return half * half


